        pipelineId: pipeline.id,
        stageId: stage.id,
        assignedUserId: user.id,
        createdById: user.id,
        status: (stage.isClosedWon ? 'WON' : stage.isClosedLost ? 'LOST' : 'OPEN') as any
      }));
      
