                <div>
                  <h3 className="font-medium text-gray-900">{u.firstName} {u.lastName}</h3>
                  <p className="text-sm text-gray-500">{isOnline ? 'Online' : 'Offline'}</p>
                </div>
              </div>
              <button
                onClick={() => handleCall(u.id)}
                disabled={callingId === u.id || u.id === userId}
                className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700 disabled:opacity-50 transition-colors"
              >
                <Phone className="w-4 h-4" />
                {callingId === u.id ? 'Calling...' : 'Call'}
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { Send, User as UserIcon, Phone } from 'lucide-react';
import Pusher from 'pusher-js';
import { getConversationsAction, getMessagesAction, sendMessageAction } from '@/modules/communication/actions/chat.actions';

export default function ChatInterface({ userId, tenantId }: { userId: string; tenantId: string }) {
  const [conversations, setConversations] = useState<any[]>([]);
  const [activeConvId, setActiveConvId] = useState<string | null>(null);
  const [messages, setMessages] = useState<any[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(true);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    // Load conversations
    getConversationsAction().then(res => {
      if (res.success) {
        setConversations(res.data);
      }
      setLoading(false);
    }).catch(err => {
      console.error('Failed to load conversations:', err);
      setLoading(false);
    });
  }, []);

  useEffect(() => {
    if (!activeConvId) return;

    // Load messages
    getMessagesAction(activeConvId).then(res => {
      if (res.success) setMessages(res.data);
    });

    // Setup Pusher
    const pusherKey = process.env.NEXT_PUBLIC_PUSHER_KEY;
    if (!pusherKey) {
      console.warn('NEXT_PUBLIC_PUSHER_KEY missing; realtime chat disabled.');
      return;
    }

    const pusher = new Pusher(pusherKey, {
      cluster: process.env.NEXT_PUBLIC_PUSHER_CLUSTER || 'mt1',
      authEndpoint: '/api/realtime/auth',
    });

    const channelName = `private-chat-tenant_${tenantId}_conv_${activeConvId}`;
    const channel = pusher.subscribe(channelName);

    channel.bind('new_message', (data: any) => {
      setMessages(prev => [...prev, data]);
    });

    return () => {
      channel.unbind_all();
      pusher.unsubscribe(channelName);
      pusher.disconnect();
    };
  }, [activeConvId, tenantId]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || !activeConvId) return;
    const content = input;
    setInput('');
    try {
      const res = await sendMessageAction({ conversationId: activeConvId, content });
      if (res && res.success && res.data) {
        setMessages(prev => {
          if (prev.find(m => m.id === res.data.id)) return prev;
          return [...prev, res.data];
        });
      }
    } catch (e) {
      console.error(e);
      // rollback or show error
    }
  };

  if (loading) return <div className="p-6 text-center text-gray-500">Loading...</div>;

  return (
    <div className="flex h-[700px] bg-white border rounded-lg shadow-sm overflow-hidden">
      {/* Sidebar */}
      <div className="w-1/3 border-r flex flex-col">
        <div className="p-4 border-b font-semibold bg-gray-50 text-gray-800">
          Conversations
        </div>
        <div className="flex-1 overflow-y-auto">
          {conversations.length === 0 ? (
            <div className="p-4 text-center text-gray-500 text-sm">No conversations found.</div>
          ) : (
            conversations.map(c => (
              <div 
                key={c.id} 
                onClick={() => setActiveConvId(c.id)}
                className={`p-4 border-b cursor-pointer hover:bg-gray-50 transition-colors ${activeConvId === c.id ? 'bg-indigo-50 border-l-4 border-l-indigo-500' : ''}`}
              >
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-gray-200 rounded-full flex items-center justify-center">
                    <UserIcon className="w-5 h-5 text-gray-500" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="font-medium text-gray-900 truncate">{c.name || 'Chat'}</p>
                    <p className="text-sm text-gray-500 truncate">Tap to view</p>
                  </div>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col">
        {activeConvId ? (
          <>
            <div className="p-4 border-b font-semibold bg-gray-50 text-gray-800 flex items-center justify-between">
              <span>Active Conversation</span>
              {conversations.find(c => c.id === activeConvId)?.targetUserId && (
                <button
                  onClick={() => {
                    const targetUserId = conversations.find(c => c.id === activeConvId)?.targetUserId;
                    if (targetUserId) {
                      window.dispatchEvent(new CustomEvent('webrtc-initiate-call', { detail: { targetUserId } }));
                    }
                  }}
                  className="flex items-center gap-1.5 px-3 py-1.5 text-sm bg-indigo-50 text-indigo-600 hover:bg-indigo-100 rounded-md transition-colors font-medium"
                >
                  <Phone className="w-4 h-4" />
                  Call
                </button>
              )}
            </div>
            <div className="flex-1 p-4 overflow-y-auto bg-gray-50/50">
              {messages.length === 0 ? (
                <div className="h-full flex items-center justify-center text-gray-500">
                  No messages yet. Say hello!
                </div>
              ) : (
                <div className="space-y-4">
                  {messages.map(m => {
                    const isMine = m.senderId === userId;
                    return (
                      <div key={m.id} className={`flex ${isMine ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-[70%] rounded-2xl px-4 py-2 ${isMine ? 'bg-indigo-600 text-white rounded-br-none' : 'bg-white border text-gray-900 rounded-bl-none shadow-sm'}`}>
                          <p>{m.content}</p>
                          {m.referenceType && m.referenceId && (
                            <div className="mt-2 text-xs bg-black/10 p-2 rounded">
                              Referenced {m.referenceType}: {m.referenceId}
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}
                  <div ref={messagesEndRef} />
                </div>
              )}
            </div>
            <div className="p-4 border-t bg-white">
              <form 
                className="flex items-center gap-2"
                onSubmit={(e) => { e.preventDefault(); handleSend(); }}
              >
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder="Type a message..." 
                  className="flex-1 bg-gray-100 border-transparent rounded-full px-4 py-2 focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-colors"
                />
                <button 
                  type="submit" 
                  disabled={!input.trim()}
                  className="p-2 bg-indigo-600 text-white rounded-full hover:bg-indigo-700 disabled:opacity-50 transition-colors"
                >
                  <Send className="w-5 h-5" />
                </button>
              </form>
            </div>
          </>
        ) : (
          <div className="flex-1 flex items-center justify-center bg-gray-50/50">
            <p className="text-gray-500">Select a conversation to start messaging.</p>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Send, User as UserIcon, Archive } from 'lucide-react';
import { getInboxAction, sendInternalMailAction, archiveMailAction } from '@/modules/communication/actions/inbox.actions';

export default function MailInterface({ userId }: { userId: string }) {
  const [inbox, setInbox] = useState<any[]>([]);
  const [activeMail, setActiveMail] = useState<any | null>(null);
  const [compose, setCompose] = useState(false);
  const [loading, setLoading] = useState(true);

  // Compose states
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [toStr, setToStr] = useState(''); // Comma separated userIds for prototype
  const [sending, setSending] = useState(false);

  const loadInbox = React.useCallback(async () => {
    const res = await getInboxAction();
    if (res.success) {
      setInbox(res.data);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- False positive: loadInbox contains only asynchronous setState after network fetch
    loadInbox();
  }, [loadInbox]);



  const handleSend = async () => {
    if (!subject || !body || !toStr) return;
    setSending(true);
    try {
      const toIds = toStr.split(',').map(s => s.trim()).filter(Boolean);
      await sendInternalMailAction({
        subject,
        bodyHtml: body,
        toIds
      });
      setCompose(false);
      setSubject('');
      setBody('');
      setToStr('');
      loadInbox();
    } catch (e) {
      console.error(e);
    } finally {
      setSending(false);
    }
  };

  const handleArchive = async (messageId: string) => {
    try {
      await archiveMailAction(messageId);
      setActiveMail(null);
      loadInbox();
    } catch (e) {
      console.error(e);
    }
  };

  if (loading) return <div className="p-6 text-center text-gray-500">Loading mailbox...</div>;

  return (
    <div className="flex h-[700px] bg-white border rounded-lg shadow-sm overflow-hidden">
      {/* Sidebar */}
      <div className="w-1/3 border-r flex flex-col">
        <div className="p-4 border-b font-semibold bg-gray-50 text-gray-800 flex justify-between items-center">
          <span>Inbox</span>
          <button 
            onClick={() => setCompose(true)}
            className="text-sm bg-indigo-600 text-white px-3 py-1 rounded hover:bg-indigo-700 transition-colors"
          >
            Compose
          </button>
        </div>
        <div className="flex-1 overflow-y-auto">
          {inbox.length === 0 ? (
            <div className="p-4 text-center text-gray-500 text-sm">Your inbox is empty.</div>
          ) : (
            inbox.map(m => (
              <div 
                key={m.id} 
                onClick={() => { setActiveMail(m); setCompose(false); }}
                className={`p-4 border-b cursor-pointer hover:bg-gray-50 transition-colors ${activeMail?.id === m.id && !compose ? 'bg-indigo-50 border-l-4 border-l-indigo-500' : ''}`}
              >
                <div className="flex flex-col gap-1">
                  <p className="font-medium text-gray-900 truncate">
                    {m.message?.thread?.subject || 'No Subject'}
                  </p>
                  <p className="text-xs text-gray-500 truncate">From: {m.message?.sender?.firstName} {m.message?.sender?.lastName}</p>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Main Mail Area */}
      <div className="flex-1 flex flex-col bg-gray-50/50">
        {compose ? (
          <div className="p-6 flex flex-col h-full bg-white">
            <h2 className="text-xl font-semibold mb-4">Compose Internal Mail</h2>
            <div className="space-y-4 flex-1 flex flex-col">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">To (User IDs comma separated)</label>
                <input 
                  type="text" 
                  value={toStr} onChange={e => setToStr(e.target.value)}
                  className="w-full border rounded p-2 focus:ring-2 focus:ring-indigo-500"
                  placeholder="e.g. 123e4567-e89b-12d3-a456-426614174000"
                />
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Subject</label>
                <input 
                  type="text" 
                  value={subject} onChange={e => setSubject(e.target.value)}
                  className="w-full border rounded p-2 focus:ring-2 focus:ring-indigo-500"
                  placeholder="Subject"
                />
              </div>
              <div className="flex-1 flex flex-col">
                <label className="block text-sm font-medium text-gray-700 mb-1">Message</label>
                <textarea 
                  value={body} onChange={e => setBody(e.target.value)}
                  className="w-full border rounded p-2 flex-1 focus:ring-2 focus:ring-indigo-500 resize-none"
                  placeholder="Type your message here..."
                />
              </div>
              <div className="flex justify-end gap-2 pt-2">
                <button 
                  onClick={() => setCompose(false)}
                  className="px-4 py-2 border rounded hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button 
                  onClick={handleSend}
                  disabled={sending || !subject || !body || !toStr}
                  className="px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700 disabled:opacity-50 flex items-center gap-2"
                >
                  {sending ? 'Sending...' : <><Send className="w-4 h-4" /> Send</>}
                </button>
              </div>
            </div>
          </div>
        ) : activeMail ? (
          <div className="p-6 flex flex-col h-full bg-white">
            <div className="flex justify-between items-start mb-6 pb-4 border-b">
              <div>
                <h2 className="text-2xl font-semibold mb-2">{activeMail.message?.thread?.subject || 'No Subject'}</h2>
                <div className="flex items-center gap-2 text-sm text-gray-600">
                  <div className="w-8 h-8 bg-gray-200 rounded-full flex items-center justify-center">
                    <UserIcon className="w-4 h-4 text-gray-500" />
                  </div>
                  <span>
                    From: <span className="font-medium text-gray-900">{activeMail.message?.sender?.firstName} {activeMail.message?.sender?.lastName}</span>
                  </span>
                  <span className="text-gray-400">•</span>
                  <span>{new Date(activeMail.createdAt).toLocaleString()}</span>
                </div>
              </div>
              <button 
                onClick={() => handleArchive(activeMail.id)}
                className="p-2 text-gray-500 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                title="Archive"
              >
                <Archive className="w-5 h-5" />
              </button>
            </div>
            <div className="flex-1 overflow-y-auto prose max-w-none text-gray-800" dangerouslySetInnerHTML={{ __html: activeMail.message?.bodyHtml || '' }} />

            {/* Structured CRM References rendering block */}
            {activeMail.message?.referenceType && activeMail.message?.referenceId && (
              <div className="mt-6 p-4 bg-indigo-50 border border-indigo-100 rounded-lg flex items-center gap-3">
                <div className="bg-indigo-600 text-white p-2 rounded">
                  <Send className="w-4 h-4" />
                </div>
                <div>
                  <p className="font-semibold text-indigo-900">Attached CRM Record</p>
                  <p className="text-sm text-indigo-700">Type: {activeMail.message.referenceType} | ID: {activeMail.message.referenceId}</p>
                </div>
                <button className="ml-auto px-4 py-2 bg-white text-indigo-600 text-sm font-medium border border-indigo-200 rounded hover:bg-indigo-50 transition-colors">
                  View Record
                </button>
              </div>
            )}
          </div>
        ) : (
          <div className="flex-1 flex items-center justify-center">
            <p className="text-gray-500">Select a message to read.</p>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useWebRTCCall } from '@/hooks/useWebRTCCall';
import { Phone, PhoneOff, Mic, MicOff, Video, VideoOff } from 'lucide-react';

interface WebRTCCallManagerProps {
  userId: string;
  tenantId: string;
}

export default function WebRTCCallManager({ userId, tenantId }: WebRTCCallManagerProps) {
  const { callState, callId, remoteUserId, localVideoRef, remoteAudioRef, acceptCall, rejectCall, endCall, initiateCall } = useWebRTCCall({ userId, tenantId });
  const [showModal, setShowModal] = useState(false);
  const [isMuted, setIsMuted] = useState(false);

  const isTerminalOrIdle = callState === 'IDLE' || callState === 'ENDED' || callState === 'FAILED' || callState === 'REJECTED' || callState === 'MISSED';
  const [prevCallState, setPrevCallState] = useState(callState);

  // Sync state during render (React recommended pattern for deriving state from props/hooks without effects)
  if (callState !== prevCallState) {
    setPrevCallState(callState);
    if (!isTerminalOrIdle) {
      setShowModal(true);
    }
  }

  useEffect(() => {
    let timeout: ReturnType<typeof setTimeout>;
    if (isTerminalOrIdle) {
      timeout = setTimeout(() => setShowModal(false), 2000); // Wait 2s to show terminal state before hiding
    }
    return () => {
      if (timeout) clearTimeout(timeout);
    };
  }, [isTerminalOrIdle]);

  useEffect(() => {
    const handleInitiateCall = (e: Event) => {
      const customEvent = e as CustomEvent<{ targetUserId: string }>;
      if (customEvent.detail?.targetUserId) {

        initiateCall(customEvent.detail.targetUserId);
      }
    };
    window.addEventListener('webrtc-initiate-call', handleInitiateCall);
    return () => window.removeEventListener('webrtc-initiate-call', handleInitiateCall);
  }, [initiateCall]);

  const handleAccept = async () => {
    await acceptCall();
  };

  const handleReject = async () => {
    await rejectCall();
  };

  const handleEndCall = async () => {
    await endCall();
  };

  const toggleMute = () => {
    // MediaStream access should ideally be exposed by the hook, but for now we will disable mute logic
    // or we'd have to expose toggleMute from the hook. To preserve hook encapsulation and satisfy TS:
    console.warn("Mute requires hook extension");
  };

  if (!showModal) return null;

  return (
    <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4 animate-in fade-in">
      <div className="bg-[#0D1326] border border-white/10 rounded-2xl w-full max-w-sm shadow-2xl overflow-hidden flex flex-col">
        <div className="p-6 flex flex-col items-center text-center">
          <div className="w-20 h-20 bg-indigo-500/20 rounded-full flex items-center justify-center mb-4 relative">
            <Phone className="w-8 h-8 text-indigo-400" />
            {callState === 'RINGING' && (
              <span className="absolute inset-0 rounded-full border-2 border-indigo-400 animate-ping opacity-75"></span>
            )}
          </div>
          <h3 className="text-xl font-display font-semibold text-white mb-1">
            {remoteUserId ? `User: ${remoteUserId.substring(0, 8)}` : 'Unknown Caller'}
          </h3>
          <p className="text-[#8891B0] text-sm mb-6">
            {callState === 'RINGING' ? 'Incoming Call...' :
             callState === 'CALLING' ? 'Calling...' :
             callState === 'CONNECTED' ? 'Call Connected' :
             callState === 'REJECTED' ? 'Call Rejected' :
             callState === 'ENDED' ? 'Call Ended' : callState}
          </p>

          <audio ref={remoteAudioRef} autoPlay />

          <div className="flex items-center justify-center gap-4 w-full">
            {callState === 'RINGING' && (
              <>
                <button 
                  onClick={handleReject}
                  className="w-12 h-12 rounded-full bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white flex items-center justify-center transition-colors"
                >
                  <PhoneOff className="w-5 h-5" />
                </button>
                <button 
                  onClick={handleAccept}
                  className="w-12 h-12 rounded-full bg-emerald-500/10 text-emerald-500 hover:bg-emerald-500 hover:text-white flex items-center justify-center transition-colors shadow-[0_0_15px_rgba(16,185,129,0.3)]"
                >
                  <Phone className="w-5 h-5" />
                </button>
              </>
            )}

            {callState === 'CONNECTED' && (
              <>
                <button 
                  onClick={toggleMute}
                  className={`w-12 h-12 rounded-full flex items-center justify-center transition-colors ${isMuted ? 'bg-amber-500 text-white' : 'bg-white/5 text-white hover:bg-white/10'}`}
                >
                  {isMuted ? <MicOff className="w-5 h-5" /> : <Mic className="w-5 h-5" />}
                </button>
                <button 
                  onClick={handleEndCall}
                  className="w-12 h-12 rounded-full bg-red-500 text-white hover:bg-red-600 flex items-center justify-center transition-colors shadow-[0_0_15px_rgba(239,68,68,0.3)]"
                >
                  <PhoneOff className="w-5 h-5" />
                </button>
              </>
            )}

            {(callState === 'CALLING') && (
              <button 
                onClick={handleEndCall}
                className="w-12 h-12 rounded-full bg-red-500/10 text-red-500 hover:bg-red-500 hover:text-white flex items-center justify-center transition-colors"
              >
                <PhoneOff className="w-5 h-5" />
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

