    { purpose: 'crm-phase26-load-test' },
    secret,
    {
      subject: userId,
      audience: 'crm-staging-load-test',
      issuer: 'crm-phase26-runner',
      expiresIn: '1h',
      algorithm: 'HS256'
    }
  );
}

