      await tx.user.createMany({ data: [{ id: userId, tenantId, email: 'test@test.com', status: 'ACTIVE', clerkId: `clerk_${userId}`, firstName: 'T', lastName: 'U' }], skipDuplicates: true });
      
      const custId = crypto.randomUUID();
