import { hashPassword, verifyPassword } from '@/lib/auth/password';
import { createSession, resolveSession, revokeCurrentSession } from '@/lib/auth/session';
import { getCurrentUser, requireAuth, checkPermission } from '@/lib/auth';
import prisma from '@db/utils/prisma';
import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import crypto from 'crypto';
import * as headers from 'next/headers';

vi.mock('next/headers', () => {
  const store = new Map<string, any>();
  return {
    cookies: vi.fn().mockReturnValue({
      get: (name: string) => store.get(name),
      set: (name: string, value: string, options: any) => store.set(name, { value, options }),
      delete: (name: string) => store.delete(name),
    }),
  };
});

describe('Phase 3: Native Authentication Core', () => {
  let tenant: any;
  let user: any;

  beforeEach(async () => {
    vi.clearAllMocks();
    (headers.cookies as any)().delete('crm_session');

    // Fixture creation uses the system path (crm_system_user / BYPASSRLS via ADMIN_DATABASE_URL).
    // This is necessary because the User table has RLS that requires app.current_tenant_id to be set,
    // which only exists during real application requests — not during test setup.
    // The application code-under-test (createSession, resolveSession, requireAuth, etc.)
    // still runs through the normal prisma client (crm_app_user / NOBYPASSRLS).
    const result = await executeAsSystem(SystemOperation.AUTH_BOOTSTRAP, async (tx) => {
      const t = await tx.tenant.create({
        data: { name: `Test Tenant ${crypto.randomUUID()}`, status: 'ACTIVE' }
      });
      const u = await tx.user.create({
        data: {
          email: `native_${crypto.randomUUID()}@test.com`,
          tenantId: t.id,
          status: 'ACTIVE',
        }
      });
      return { tenant: t, user: u };
    });
    tenant = result.tenant;
    user = result.user;
  });

  afterEach(async () => {
    // Clean up fixtures using the system path so RLS doesn't block cleanup.
    if (user?.id) {
      await executeAsSystem(SystemOperation.AUTH_BOOTSTRAP, async (tx) => {
        await tx.authSession.deleteMany({ where: { userId: user.id } });
        await tx.user.delete({ where: { id: user.id } });
      });
    }
    if (tenant?.id) {
      await executeAsSystem(SystemOperation.AUTH_BOOTSTRAP, async (tx) => {
        await tx.tenant.delete({ where: { id: tenant.id } });
      });
    }
  });


  describe('Password Hashing', () => {
    it('1. Password hashes are not plaintext', async () => {
      const pwd = 'securePassword123';
      const hash = await hashPassword(pwd);
      expect(hash).not.toContain(pwd);
      expect(hash).toContain('$argon2id$');
    });

    it('2. Same password can be verified', async () => {
      const pwd = 'securePassword123';
      const hash = await hashPassword(pwd);
      const isValid = await verifyPassword(pwd, hash);
      expect(isValid).toBe(true);
    });

    it('3. Wrong password fails', async () => {
      const hash = await hashPassword('correctPassword');
      const isValid = await verifyPassword('wrongPassword', hash);
      expect(isValid).toBe(false);
    });
  });

  describe('Session Management', () => {
    it('8. Valid session resolves correct User', async () => {
      await createSession(user.id);
      const sessionUser = await resolveSession();
      expect(sessionUser).not.toBeNull();
      expect(sessionUser?.id).toBe(user.id);
    });

    it('11. Unknown session is rejected', async () => {
      (headers.cookies as any)().set('crm_session', 'randominvalidtoken', {});
      const sessionUser = await resolveSession();
      expect(sessionUser).toBeNull();
    });

    it('12. Logout revokes session', async () => {
      await createSession(user.id);
      const sessionBefore = await resolveSession();
      expect(sessionBefore).not.toBeNull();
      
      await revokeCurrentSession();
      
      // Cookie is deleted by the revoke function, but even if it was present, the DB row is revoked
      const sessionAfter = await resolveSession();
      expect(sessionAfter).toBeNull();
    });
  });

  describe('Backend Authorization Migration', () => {
    it('13. getCurrentUser returns User from native session', async () => {
      await createSession(user.id);
      const currentUser = await getCurrentUser();
      expect(currentUser).not.toBeNull();
      expect(currentUser?.id).toBe(user.id);
    });

    it('14. getCurrentUser returns null when no session exists', async () => {
      const currentUser = await getCurrentUser();
      expect(currentUser).toBeNull();
    });

    it('15. requireAuth throws when no session exists', async () => {
      await expect(requireAuth()).rejects.toThrow('Unauthorized');
    });

    it('16. requireAuth returns User when valid session exists', async () => {
      await createSession(user.id);
      const authUser = await requireAuth();
      expect(authUser.id).toBe(user.id);
    });

    it('17. checkPermission denies without session', async () => {
      const hasPerm = await checkPermission('USER', 'READ');
      expect(hasPerm).toBe(false);
    });
  });
});

import { describe, it, expect, beforeAll, afterAll, vi } from 'vitest';
import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import { inviteEmployee } from '@/modules/users/user.service';
import { ensureUserProvisioned } from '@/modules/auth/services/provisioning.service';
import * as authLib from '@/lib/auth';

// Mock clerkClient to prevent real network calls
vi.mock('@clerk/nextjs/server', () => {
  return {
    clerkClient: () => Promise.resolve({
      invitations: {
        createInvitation: vi.fn().mockResolvedValue({ id: 'inv_mock_123', status: 'pending' })
      }
    }),
    auth: vi.fn()
  };
});

describe('Onboarding Lifecycle & Security Invariants', () => {
  let tenant1Id: string;
  let tenant2Id: string;
  let t1AdminId: string;
  let t1DeptHeadId: string;
  let t1DeptId: string;
  
  beforeAll(async () => {
    // Bootstrap test data
    await executeAsSystem(SystemOperation.DEMO_SEED, async (tx) => {
      const t1 = await tx.tenant.create({ data: { name: 'Test Tenant 1', status: 'ACTIVE' } });
      const t2 = await tx.tenant.create({ data: { name: 'Test Tenant 2', status: 'ACTIVE' } });
      tenant1Id = t1.id;
      tenant2Id = t2.id;
      
      const adminRole = await tx.role.create({ data: { name: 'TENANT_ADMIN', tenantId: t1.id } });
      const deptHeadRole = await tx.role.create({ data: { name: 'DEPARTMENT_HEAD', tenantId: t1.id } });
      const memberRole = await tx.role.create({ data: { name: 'MEMBER', tenantId: t1.id } });
      
      // Seed roles for tenant 2
      await tx.role.create({ data: { name: 'TENANT_ADMIN', tenantId: t2.id } });
      await tx.role.create({ data: { name: 'MEMBER', tenantId: t2.id } });

      const dept = await tx.department.create({ data: { name: 'Engineering', tenantId: t1.id } });
      t1DeptId = dept.id;

      // Admin user
      const admin = await tx.user.create({
        data: {
          email: 'admin@t1.com',
          clerkId: 'c_admin_1',
          tenantId: t1.id,
          status: 'ACTIVE',
          userRoles: { create: { roleId: adminRole.id, tenantId: t1.id } }
        }
      });
      t1AdminId = admin.id;

      // Dept Head user
      const deptHead = await tx.user.create({
        data: {
          email: 'dh@t1.com',
          clerkId: 'c_dh_1',
          tenantId: t1.id,
          departmentId: dept.id,
          status: 'ACTIVE',
          userRoles: { create: { roleId: deptHeadRole.id, tenantId: t1.id } }
        }
      });
      t1DeptHeadId = deptHead.id;
      
      // Setup permission mock for simplicity
      const perm = await tx.permission.upsert({
        where: { resource_action: { resource: 'USER', action: 'CREATE' } },
        update: {},
        create: { resource: 'USER', action: 'CREATE' }
      });
      await tx.rolePermission.create({ data: { roleId: adminRole.id, permissionId: perm.id, tenantId: t1.id } });
      await tx.rolePermission.create({ data: { roleId: deptHeadRole.id, permissionId: perm.id, tenantId: t1.id } });
    });
  });

  afterAll(async () => {
    // Teardown skipped because AuditLog append-only Postgres trigger prevents Tenant deletion.
    // The test DB isolates tests by creating a unique tenant per test suite.
  });

  it('CASE A & B: Admin invites employee, auto-linking is strictly BLOCKED', async () => {
    const uniqueSuffix = Date.now().toString();
    // Mock requireAuth to return Admin
    const mockAdmin = await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => tx.user.findUnique({ where: { id: t1AdminId }, include: { userRoles: { include: { role: true } } } }));
    vi.spyOn(authLib, 'requireAuth').mockResolvedValue(mockAdmin as any);
    vi.spyOn(authLib, 'requireTenant').mockResolvedValue(tenant1Id);
    vi.spyOn(authLib, 'requirePermission').mockResolvedValue(undefined as any);
    
    const email = `newemp_${uniqueSuffix}@t1.com`;
    await inviteEmployee(email, 'MEMBER');
    
    // Check local user is INVITED
    const invitedUser = await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) =>
      tx.user.findFirst({ where: { email } })
    );
    expect(invitedUser).toBeDefined();
    expect(invitedUser?.status).toBe('INVITED');
    expect(invitedUser?.clerkId).toBeNull();
    
    // Simulate Clerk user.created
    const webhookPayload = {
      id: 'c_newemp_1',
      email_addresses: [{ email_address: email }]
    };
    
    // Auto-linking must fail (return null) because the user is INVITED.
    const linkedUser = await ensureUserProvisioned(webhookPayload);
    expect(linkedUser).toBeNull();
    
    // Verify DB still says INVITED
    const activeUser = await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) =>
      tx.user.findFirst({ where: { email } })
    );
    expect(activeUser?.status).toBe('INVITED');
  });

  it('CASE C: Unknown Clerk User yields no CRM account', async () => {
    const uniqueSuffix = Date.now().toString();
    const webhookPayload = {
      id: `c_unknown_${uniqueSuffix}`,
      email_addresses: [{ email_address: `rando_${uniqueSuffix}@hacker.com` }]
    };
    
    const linkedUser = await ensureUserProvisioned(webhookPayload);
    expect(linkedUser).toBeNull();
    
    const dbUser = await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) =>
      tx.user.findFirst({ where: { email: `rando_${uniqueSuffix}@hacker.com` } })
    );
    expect(dbUser).toBeNull();
  });

  it('CASE E: Role Forgery (Dept Head cannot invite TENANT_ADMIN)', async () => {
    const uniqueSuffix = Date.now().toString();
    const mockDH = await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => tx.user.findUnique({ where: { id: t1DeptHeadId }, include: { userRoles: { include: { role: true } } } }));
    vi.spyOn(authLib, 'requireAuth').mockResolvedValue(mockDH as any);
    vi.spyOn(authLib, 'requireTenant').mockResolvedValue(tenant1Id);
    
    await expect(inviteEmployee(`admin2_${uniqueSuffix}@t1.com`, 'TENANT_ADMIN', t1DeptId))
      .rejects.toThrow('Forbidden: Only a TENANT_ADMIN can assign or invite the TENANT_ADMIN role.');
  });

  it('CASE G: Department Forgery (Dept Head cannot invite to another department)', async () => {
    const uniqueSuffix = Date.now().toString();
    const mockDH = await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => tx.user.findUnique({ where: { id: t1DeptHeadId }, include: { userRoles: { include: { role: true } } } }));
    vi.spyOn(authLib, 'requireAuth').mockResolvedValue(mockDH as any);
    vi.spyOn(authLib, 'requireTenant').mockResolvedValue(tenant1Id);
    
    // Try to invite to a non-existent/different department
    await expect(inviteEmployee(`otherdept_${uniqueSuffix}@t1.com`, 'MEMBER', 'some-other-dept-id'))
      .rejects.toThrow('Forbidden: You cannot manage employees outside your department.');
  });

  it('CASE H: Duplicate Webhook is Idempotent for ACTIVE users', async () => {
    const uniqueSuffix = Date.now().toString();
    const email = `dupwebhook_${uniqueSuffix}@t1.com`;
    const mockAdmin = await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => tx.user.findUnique({ where: { id: t1AdminId }, include: { userRoles: { include: { role: true } } } }));
    
    // Create an ACTIVE user directly (simulate they already completed onboarding)
    await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => {
       await tx.user.create({
         data: {
           email,
           clerkId: `c_dup_${uniqueSuffix}`,
           tenantId: tenant1Id,
           status: 'ACTIVE'
         }
       });
    });
    
    const webhookPayload = {
      id: `c_dup_${uniqueSuffix}`,
      primary_email_address_id: 'test_email_id',
      email_addresses: [{ id: 'test_email_id', email_address: email }]
    };
    
    const res1 = await ensureUserProvisioned(webhookPayload);
    expect(res1?.status).toBe('ACTIVE');
    
    // Second webhook identical
    const res2 = await ensureUserProvisioned(webhookPayload);
    expect(res2?.status).toBe('ACTIVE');
    
    // Total users with this email is 1
    const count = await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) =>
      tx.user.count({ where: { email } })
    );
    expect(count).toBe(1);
  });
  
  it('CASE D: Email Mismatch yields no link', async () => {
    const uniqueSuffix = Date.now().toString();
    const email = `correct_${uniqueSuffix}@t1.com`;
    const mockAdmin = await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => tx.user.findUnique({ where: { id: t1AdminId }, include: { userRoles: { include: { role: true } } } }));
    vi.spyOn(authLib, 'requireAuth').mockResolvedValue(mockAdmin as any);
    vi.spyOn(authLib, 'requireTenant').mockResolvedValue(tenant1Id);
    
    await inviteEmployee(email, 'MEMBER');
    
    const webhookPayload = {
      id: `c_wrong_${uniqueSuffix}`,
      email_addresses: [{ email_address: `wrong_${uniqueSuffix}@t1.com` }]
    };
    
    const linkedUser = await ensureUserProvisioned(webhookPayload);
    expect(linkedUser).toBeNull();
    
    // correct email user is still INVITED
    const u = await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) =>
      tx.user.findFirst({ where: { email } })
    );
    expect(u?.status).toBe('INVITED');
    expect(u?.clerkId).toBeNull();
  });
});

/**
 * Phase 8R Security Remediation Tests
 *
 * Validates all three findings from the Phase 8 forensic audit:
 *  8-A: Customer Timeline must not leak unrelated tenant-wide communication records
 *  8-B: Diagnostic route must not contain hardcoded email; auth must be enforced
 *  8-C: seed-demo route must not expose raw Prisma User object fields
 */

import { describe, it, expect, beforeAll, afterAll, vi } from 'vitest';
import { executeAsSystem, SystemOperation } from '@db/utils/prisma-system';
import { getCustomerTimeline } from '@/modules/crm/customer/customer.timeline.service';
import { GET as diagnosticGET } from '@/app/api/diagnostic/route';
import { GET as seedDemoGET } from '@/app/api/seed-demo/route';
import { NextRequest } from 'next/server';
import * as crypto from 'crypto';
import fs from 'fs';
import path from 'path';

// ─────────────────────────────────────────────────────────────────────────────
// Auth mock
// ─────────────────────────────────────────────────────────────────────────────
vi.mock('@/lib/auth', () => ({
  requireAuth: vi.fn(),
  requireTenant: vi.fn(),
  requirePermission: vi.fn(),
  checkPermission: vi.fn(),
}));

import { requireAuth, requireTenant, requirePermission } from '@/lib/auth';

// ─────────────────────────────────────────────────────────────────────────────
// Shared test data
// ─────────────────────────────────────────────────────────────────────────────
const tenantAId = crypto.randomUUID();
const tenantBId = crypto.randomUUID();
const userAId = crypto.randomUUID();
const userBId = crypto.randomUUID();
const adminId = crypto.randomUUID();
const customerAId = crypto.randomUUID();
const customerBId = crypto.randomUUID();

// ─────────────────────────────────────────────────────────────────────────────
// Setup / Teardown
// ─────────────────────────────────────────────────────────────────────────────
beforeAll(async () => {
  await executeAsSystem(SystemOperation.SECURITY_AUDIT, async (tx) => {
    // Create two tenants
    await tx.tenant.createMany({
      data: [
        { id: tenantAId, name: '8R-TenantA', status: 'ACTIVE' },
        { id: tenantBId, name: '8R-TenantB', status: 'ACTIVE' },
      ]
    });

    // Create users
    await tx.user.createMany({
      data: [
        { id: userAId, tenantId: tenantAId, email: 'user-a-8r@test.com', status: 'ACTIVE' },
        { id: userBId, tenantId: tenantBId, email: 'user-b-8r@test.com', status: 'ACTIVE' },
        { id: adminId, tenantId: tenantAId, email: 'admin-8r@test.com', status: 'ACTIVE' },
      ]
    });

    // Assign tenant owners
    await tx.tenant.update({ where: { id: tenantAId }, data: { ownerId: userAId } });
    await tx.tenant.update({ where: { id: tenantBId }, data: { ownerId: userBId } });

    // Create customers
    await tx.customer.createMany({
      data: [
        { id: customerAId, tenantId: tenantAId, name: '8R-CustomerA', normalizedName: '8r-customera', status: 'ACTIVE' },
        { id: customerBId, tenantId: tenantAId, name: '8R-CustomerB', normalizedName: '8r-customerb', status: 'ACTIVE' },
      ]
    });

    // Create MailThread in tenantA (NOT linked to any customer)
    const mailThread = await tx.mailThread.create({
      data: {
        tenantId: tenantAId,
        subject: 'Tenant-wide unrelated email thread',
      }
    });

    // Add a message to the mail thread
    await tx.mailMessage.create({
      data: {
        tenantId: tenantAId,
        threadId: mailThread.id,
        senderId: userAId,
        bodyHtml: '<p>Unrelated email body</p>',
        bodyText: 'Unrelated email body',
      }
    });

    // Create ChatConversation in tenantA (NOT linked to customerA or customerB)
    await tx.chatConversation.create({
      data: {
        tenantId: tenantAId,
        type: 'DIRECT',
      }
    });
  });
});

afterAll(async () => {
  // Cleanup is handled by FK cascades; customers/users/tenants with prefix 8R-
  // We leave the data — test isolation is handled by unique IDs.
});

// ─────────────────────────────────────────────────────────────────────────────
// 8-A: Customer Timeline — No unrelated communication leakage
// ─────────────────────────────────────────────────────────────────────────────
describe('8-A: Customer Timeline — No unscoped communication leakage', () => {
  const setupAuthForTimeline = () => {
    vi.mocked(requireAuth).mockResolvedValue({ id: userAId, tenantId: tenantAId } as any);
    vi.mocked(requireTenant).mockResolvedValue(tenantAId);
    vi.mocked(requirePermission).mockResolvedValue(true as any);
  };

  it('should return timeline for Customer A without leaking unrelated MailThread records', async () => {
    setupAuthForTimeline();
    const result = await getCustomerTimeline({ customerId: customerAId });

    expect(result.data).toBeDefined();

    // All returned items must only be for customer A — not tenant-wide emails
    const emailItems = result.data.filter(e => e.type === 'EMAIL');
    expect(emailItems).toHaveLength(0);

    // The unrelated mail thread subject must never appear
    const subjectAppears = result.data.some(e => e.title === 'Tenant-wide unrelated email thread');
    expect(subjectAppears).toBe(false);
  });

  it('should return timeline for Customer A without leaking unrelated ChatConversation records', async () => {
    setupAuthForTimeline();
    const result = await getCustomerTimeline({ customerId: customerAId });

    const messageItems = result.data.filter(e => e.type === 'MESSAGE');
    expect(messageItems).toHaveLength(0);
  });

  it('Customer B timeline must not show Customer A data', async () => {
    setupAuthForTimeline();

    const resultA = await getCustomerTimeline({ customerId: customerAId });
    const resultB = await getCustomerTimeline({ customerId: customerBId });

    // IDs from timeline A must not appear in timeline B
    const idsFromA = new Set(resultA.data.map(e => e.id));
    const overlap = resultB.data.filter(e => idsFromA.has(e.id));
    expect(overlap).toHaveLength(0);
  });

  it('tenant isolation: Timeline from Tenant A must not contain Tenant B data', async () => {
    // Auth is for Tenant A's user
    setupAuthForTimeline();

    const result = await getCustomerTimeline({ customerId: customerAId });

    // No items should have tenantB content by our test data design
    // The withTenant middleware enforces RLS at DB level — this verifies no bypass
    const tenantBItems = result.data.filter(e =>
      (e.title || '').includes('TenantB') ||
      (e.description || '').includes('TenantB')
    );
    expect(tenantBItems).toHaveLength(0);
  });

  it('Unauthenticated request must be denied', async () => {
    vi.mocked(requireAuth).mockRejectedValue(new Error('Unauthorized'));

    await expect(
      getCustomerTimeline({ customerId: customerAId })
    ).rejects.toThrow('Unauthorized');
  });

  it('CUSTOMER:READ permission required — missing permission must deny', async () => {
    vi.mocked(requireAuth).mockResolvedValue({ id: userAId, tenantId: tenantAId } as any);
    vi.mocked(requireTenant).mockResolvedValue(tenantAId);
    vi.mocked(requirePermission).mockRejectedValue(new Error('Forbidden'));

    await expect(
      getCustomerTimeline({ customerId: customerAId })
    ).rejects.toThrow('Forbidden');
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// 8-A: Regression — source code must not reference unscoped mailThread/chat queries
// ─────────────────────────────────────────────────────────────────────────────
describe('8-A: Regression — source must not contain unscoped communication queries', () => {
  it('timeline service must not contain an unscoped mailThread.findMany({ where: { tenantId } }) without customerId', () => {
    const serviceFile = path.join(
      process.cwd(),
      'src/modules/crm/customer/customer.timeline.service.ts'
    );
    const source = fs.readFileSync(serviceFile, 'utf8');

    // The original security defect was: mailThread.findMany({ where: { tenantId }, ... })
    // without customerId — which leaked all tenant emails to any customer timeline.
    // We enforce that EVERY mailThread.findMany call must contain customerId in its where clause.
    const findManyCalls = source.match(/mailThread\.findMany\s*\([\s\S]*?\)/g);
    if (findManyCalls) {
      for (const call of findManyCalls) {
        // Must contain customerId in the query
        expect(call).toMatch(/customerId/);
      }
    }
  });

  it('timeline service must not contain an unscoped chatConversation.findMany() without customerId', () => {
    const serviceFile = path.join(
      process.cwd(),
      'src/modules/crm/customer/customer.timeline.service.ts'
    );
    const source = fs.readFileSync(serviceFile, 'utf8');

    // Same invariant: EVERY chatConversation.findMany must be scoped by customerId.
    const findManyCalls = source.match(/chatConversation\.findMany\s*\([\s\S]*?\)/g);
    if (findManyCalls) {
      for (const call of findManyCalls) {
        expect(call).toMatch(/customerId/);
      }
    }
  });
});

// ─────────────────────────────────────────────────────────────────────────────
// 8-B: Diagnostic Route — No hardcoded email; Auth enforced
// ─────────────────────────────────────────────────────────────────────────────
describe('8-B: Diagnostic Route — hardcoded email removed; authorization intact', () => {
  it('source code must not contain the hardcoded developer email', () => {
    const routeFile = path.join(
      process.cwd(),
      'src/app/api/diagnostic/route.ts'
    );
    const source = fs.readFileSync(routeFile, 'utf8');

    expect(source).not.toContain('aruneshsharma2004');
    expect(source).not.toContain('aruneshsharma2004@gmail.com');
  });

  it('unauthenticated request must be denied (no Clerk headers → throws)', async () => {
    const req = new NextRequest('http://localhost/api/diagnostic', { method: 'GET' });
    const res = await diagnosticGET(req, {});
    // Without auth headers, requireAuth() throws → handler returns non-200
    expect(res.status).not.toBe(200);
  });

  it('response must not expose raw database credentials or connection strings', async () => {
    const req = new NextRequest('http://localhost/api/diagnostic', { method: 'GET' });
    const res = await diagnosticGET(req, {});
    const body = JSON.stringify(await res.json().catch(() => ({})));

    expect(body).not.toMatch(/postgres:\/\//);
    expect(body).not.toMatch(/postgresql:\/\//);
    expect(body).not.toContain(process.env.DATABASE_URL || 'SENTINEL_NOT_PRESENT');
  });

  it('response must not expose clerkId or tenantId raw values', async () => {
    // Without valid auth this returns error; verify it doesn't leak raw values
    const req = new NextRequest('http://localhost/api/diagnostic');
    const res = await diagnosticGET(req, {});
    const body = await res.json().catch(() => ({}));
    const bodyStr = JSON.stringify(body);

    // Clerk IDs begin with 'user_' — verify they are not serialized
    expect(bodyStr).not.toMatch(/user_[A-Za-z0-9]+/);
