describe('S15.2D — Health / Readiness Probe', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    redisEnabled = true;
  });

  afterEach(() => {
    redisEnabled = true;
  });

  it('should return 200 ready when PostgreSQL and Redis are both healthy', async () => {
    mockPrisma.$queryRaw.mockResolvedValueOnce([{ '?column?': 1 }]);
    mockRedis.ping.mockResolvedValueOnce('PONG');

    const { GET } = await import('@/app/api/health/ready/route');
    const res = await (GET as any)();
    const body = await res.json();

    expect(res.status).toBe(200);
    expect(body.status).toBe('ready');
    expect(body.components.postgres).toBe('ok');
    expect(body.components.redis).toBe('ok');
  });

  it('should return 503 when PostgreSQL is unavailable', async () => {
    mockPrisma.$queryRaw.mockRejectedValueOnce(new Error('DB connection refused'));
    // Redis doesn't matter here since Postgres failed, but we provide it for completeness
    mockRedis.ping.mockResolvedValueOnce('PONG');

    const { GET } = await import('@/app/api/health/ready/route');
    const res = await (GET as any)();
    const body = await res.json();

    expect(res.status).toBe(503);
    expect(body.status).toBe('not_ready');
    expect(body.components.postgres).toBe('unavailable');
    expect(JSON.stringify(body)).not.toMatch(/postgres:\/\//);
  });

  it('should return 200 degraded when Redis is unavailable but PostgreSQL is healthy', async () => {
    mockPrisma.$queryRaw.mockResolvedValueOnce([{ '?column?': 1 }]);
    mockRedis.ping.mockRejectedValueOnce(new Error('Redis timeout'));

    const { GET } = await import('@/app/api/health/ready/route');
    const res = await (GET as any)();
    const body = await res.json();

    expect(res.status).toBe(200);
    expect(body.status).toBe('degraded');
    expect(body.components.postgres).toBe('ok');
    expect(body.components.redis).toBe('unavailable');
  });

  it('should return 200 degraded when Redis is completely unconfigured', async () => {
    redisEnabled = false;
    mockPrisma.$queryRaw.mockResolvedValueOnce([{ '?column?': 1 }]);

    const { GET } = await import('@/app/api/health/ready/route');
    const res = await (GET as any)();
    const body = await res.json();

    expect(res.status).toBe(200);
    expect(body.status).toBe('degraded');
    expect(body.components.redis).toBe('unconfigured');
  });

  it('should NOT expose credentials or internal topology in health response', async () => {
    mockPrisma.$queryRaw.mockResolvedValueOnce([{ '?column?': 1 }]);
    mockRedis.ping.mockResolvedValueOnce('PONG');

    const { GET } = await import('@/app/api/health/ready/route');
    const res = await (GET as any)();
    const body = await res.json();
    const bodyStr = JSON.stringify(body);

    expect(bodyStr).not.toMatch(/password/i);
    expect(bodyStr).not.toMatch(/secret/i);
    expect(bodyStr).not.toMatch(/DATABASE_URL/i);
    expect(bodyStr).not.toMatch(/REDIS_URL/i);
    expect(bodyStr).not.toMatch(/stack/i);
    expect(bodyStr).not.toMatch(/at Object\./);
    expect(body).toHaveProperty('status');
    expect(body).toHaveProperty('components');
  });
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { withJobContext } from '../../lib/queue/worker';
import { getContext } from '../../lib/observability/context';
import { SecureJobEnvelope } from '../../lib/queue/types';

// Use proper RFC 4122 UUIDs so assertValidTenantId passes.
// The security hardening in database/utils/tenant-id.ts enforces UUID-only tenant IDs
// to prevent SQL injection in raw queries.
const TENANT_1 = '11111111-aaaa-4111-8111-000000000001';
const TENANT_2 = '22222222-bbbb-4222-9222-000000000002';
const TENANT_A = 'aaaaaaaa-cccc-4aaa-8aaa-000000000001';
const TENANT_B = 'bbbbbbbb-dddd-4bbb-9bbb-000000000002';
const TENANT_5 = '55555555-eeee-4555-8555-000000000005';
const TENANT_6 = '66666666-ffff-4666-9666-000000000006';
const TENANT_8 = '88888888-aaaa-4888-8888-000000000008';

describe('S15.3A Background Job Observability Context', () => {

  // Mock withTenant from prisma-tenant — must be at top-level (vitest hoists vi.mock)
  vi.mock('../../../database/utils/prisma-tenant', () => {
    const mockTx = {
      $executeRawUnsafe: vi.fn(),
      $executeRaw: vi.fn(),
      $queryRawUnsafe: vi.fn().mockResolvedValue([]),
      $queryRaw: vi.fn().mockResolvedValue([]),
      idempotencyKey: { create: vi.fn() },
    };
    return {
      withTenant: vi.fn().mockReturnValue({
        $transaction: async (fn: any) => fn(mockTx)
      }),
      withTenantTransaction: vi.fn()
    };
  });

  // We mock Logger to avoid spewing logs in tests
  vi.mock('../../lib/logger/logger', () => ({
    Logger: {
      info: vi.fn(),
      error: vi.fn(),
    }
  }));

  beforeEach(() => {
    vi.clearAllMocks();
  });

  afterEach(() => {
    // Ensure context is cleared globally if tests fail
    expect(getContext()).toBeUndefined();
  });

  it('Test 1: Single background job receives job context', async () => {
    const envelope: SecureJobEnvelope<any> = {
      jobId: 'job-1',
      jobType: 'TEST',
      tenantId: TENANT_1,
      actorType: 'SYSTEM',
      payload: {},
      schemaVersion: '1.0',
      correlationId: ''
    };

    let capturedContext: any;
    await withJobContext(envelope, async () => {
      capturedContext = getContext();
      return true;
    });

    expect(capturedContext).toBeDefined();
    expect(capturedContext.jobId).toBe('job-1');
  });

  it('Test 2: Tenant context is preserved from trusted job metadata', async () => {
    const envelope: SecureJobEnvelope<any> = {
      jobId: 'job-2',
      jobType: 'TEST',
      tenantId: TENANT_2,
      actorType: 'SYSTEM',
      payload: {},
      schemaVersion: '1.0',
      correlationId: ''
    };

    let capturedContext: any;
    await withJobContext(envelope, async () => {
      capturedContext = getContext();
      return true;
    });

    expect(capturedContext.tenantId).toBe(TENANT_2);
  });

  it('Test 4: Two concurrent jobs with different tenants never cross context', async () => {
    const envelopeA: SecureJobEnvelope<any> = {
      jobId: 'job-a',
      jobType: 'TEST',
      tenantId: TENANT_A,
      actorType: 'SYSTEM',
      payload: {},
      schemaVersion: '1.0',
      correlationId: ''
    };

    const envelopeB: SecureJobEnvelope<any> = {
      jobId: 'job-b',
      jobType: 'TEST',
      tenantId: TENANT_B,
      actorType: 'SYSTEM',
      payload: {},
      schemaVersion: '1.0',
      correlationId: ''
    };

    let contextA: any;
    let contextB: any;

    const promiseA = withJobContext(envelopeA, async () => {
      await new Promise(r => setTimeout(r, 10)); // Force yield
      contextA = getContext();
    });

    const promiseB = withJobContext(envelopeB, async () => {
      await new Promise(r => setTimeout(r, 10)); // Force yield
      contextB = getContext();
    });

    await Promise.all([promiseA, promiseB]);

    expect(contextA.tenantId).toBe(TENANT_A);
    expect(contextB.tenantId).toBe(TENANT_B);
  });

  it('Test 5: Context cleared after successful completion', async () => {
    const envelope: SecureJobEnvelope<any> = {
      jobId: 'job-5',
      jobType: 'TEST',
      tenantId: TENANT_5,
      actorType: 'SYSTEM',
      payload: {},
      schemaVersion: '1.0',
      correlationId: ''
    };

    await withJobContext(envelope, async () => {
      expect(getContext()).toBeDefined();
    });

    expect(getContext()).toBeUndefined();
  });

  it('Test 6: Context cleared after failure', async () => {
    const envelope: SecureJobEnvelope<any> = {
      jobId: 'job-6',
      jobType: 'TEST',
      tenantId: TENANT_6,
      actorType: 'SYSTEM',
      payload: {},
      schemaVersion: '1.0',
      correlationId: ''
    };

    await expect(withJobContext(envelope, async () => {
      expect(getContext()).toBeDefined();
      throw new Error('Deliberate job failure');
    })).rejects.toThrow('Deliberate job failure');

    expect(getContext()).toBeUndefined();
  });

  it('Test 8: No HTTP requestId is fabricated for jobs that have none', async () => {
    const envelope: SecureJobEnvelope<any> = {
      jobId: 'job-8',
      jobType: 'TEST',
      tenantId: TENANT_8,
      actorType: 'SYSTEM',
      payload: {},
      schemaVersion: '1.0',
      correlationId: ''
    };

    let capturedContext: any;
    await withJobContext(envelope, async () => {
      capturedContext = getContext();
      return true;
    });
    
    // correlationId is empty, so requestId should be undefined or empty, not fabricated.
    expect(capturedContext.requestId).toBeFalsy();
  });

});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { withServerActionContext } from '@/lib/observability/server-action';
import { getContext, setTenantContext, withContext } from '@/lib/observability/context';
import { requireTenant } from '@/lib/auth';

// Mock headers
const mockHeaders: Map<string, string> = new Map();
vi.mock('next/headers', () => ({
  headers: vi.fn(async () => mockHeaders),
}));

// Mock auth (for testing negative auth behavior)
vi.mock('@/lib/auth', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@/lib/auth')>();
  return {
    ...actual,
    requireTenant: vi.fn(async () => {
      // Simulate resolving a tenant securely
      const tenantId = 'tenant-secure-123';
      setTenantContext(tenantId);
      return tenantId;
    }),
  };
});

describe('S15.5 FND-15.4-01: Server Action Observability Context', () => {
  beforeEach(() => {
    mockHeaders.clear();
    vi.clearAllMocks();
  });

  it('STRONG: missing correlation header generates new requestId', async () => {
    const action = withServerActionContext(async () => {
      return getContext()?.requestId;
    });

    const result = await action();
    expect(result).toBeDefined();
    expect(result?.length).toBeGreaterThan(10);
  });

  it('STRONG: valid correlation header is accepted', async () => {
    mockHeaders.set('x-correlation-id', 'test-req-123');
    const action = withServerActionContext(async () => {
      return getContext()?.requestId;
    });

    const result = await action();
    expect(result).toBe('test-req-123');
  });

  it('STRONG: malformed or oversized correlation header generates new requestId', async () => {
    const invalidId = 'a'.repeat(100);
    mockHeaders.set('x-correlation-id', invalidId);

    const action = withServerActionContext(async () => {
      return getContext()?.requestId;
    });

    const result = await action();
    expect(result).toBeDefined();
    expect(result).not.toBe(invalidId);
  });

  it('STRONG: thrown errors are unchanged', async () => {
    const action = withServerActionContext(async () => {
      throw new Error('Business Logic Error');
    });

    await expect(action()).rejects.toThrow('Business Logic Error');
  });

  it('STRONG: successful return values are unchanged', async () => {
    const action = withServerActionContext(async (a: number, b: number) => {
      return a + b;
    });

    const result = await action(2, 3);
    expect(result).toBe(5);
  });

  it('STRONG: context is cleaned up after failure and success', async () => {
    const successAction = withServerActionContext(async () => true);
    const failAction = withServerActionContext(async () => { throw new Error('fail'); });

    await successAction();
    expect(getContext()).toBeUndefined(); // Should not leak

    try {
      await failAction();
    } catch {}
    expect(getContext()).toBeUndefined();
  });

  it('STRONG: setTenantContext strictly isolates and propagates secure tenant', async () => {
    const action = withServerActionContext(async () => {
      await requireTenant();
      return getContext()?.tenantId;
    });

    const result = await action();
    expect(result).toBe('tenant-secure-123');
  });

  it('STRONG: conflicting tenant context throws context conflict error', async () => {
    // Attempt to override tenant B when tenant A is already established
    const task = new Promise<void>((resolve, reject) => {
      withContext({ tenantId: 'existing-tenant-A' }, async () => {
        try {
          // A malicious or logically flawed sub-call attempts to establish tenant B
          setTenantContext('malicious-tenant-B');
          resolve();
        } catch (err: any) {
          reject(err);
        }
      });
    });

    await expect(task).rejects.toThrow(/Context Conflict: Attempted to overwrite existing tenant existing-tenant-A with malicious-tenant-B/);
  });

  it('STRONG: concurrent actions do not leak context', async () => {
    const results: string[] = [];

    const action1 = withServerActionContext(async () => {
      // Simulate yielding to let another action execute
      await new Promise(r => setTimeout(r, 10));
      return getContext()?.requestId;
    });

    const action2 = withServerActionContext(async () => {
      await new Promise(r => setTimeout(r, 5));
      return getContext()?.requestId;
    });

    mockHeaders.set('x-correlation-id', 'req-1');
    const t1 = action1();

    // Let event loop tick so action1 reads headers before we mutate mockHeaders
    await new Promise(r => setTimeout(r, 0));

    // Switch header before executing action2
    mockHeaders.set('x-correlation-id', 'req-2');
    const t2 = action2();

    const [r1, r2] = await Promise.all([t1, t2]);

    // Expect strict isolation
    expect(r1).toBe('req-1');
    expect(r2).toBe('req-2');
  });
});

