    text: async () => JSON.stringify({ 
      from: 'customer@acme.com', 
      subject: 'Re: Proposal', 
      text: 'Looks good.',
      attachments: [{ filename: 'contract.pdf', content: 'buffer' }],
      headers: { 'in-reply-to': '<msg-123@saas>' }
